component.css:
.apd{position:relative;width:100%;aspect-ratio:3/2;container-type:size;background:transparent;opacity:1;transition:opacity .6s;font-family:Roboto,"Noto Sans","PingFang SC","Microsoft YaHei",sans-serif}
.apd.off{opacity:0}
.apd-scrim{position:absolute;inset:0;background:rgba(0,0,0,.16);opacity:0;transition:opacity .2s}
.apd-scrim.on{opacity:1}
.apd-flash{position:absolute;inset:0;background:#fff;opacity:0;pointer-events:none;z-index:9}
.apd-flash.go{animation:apFlash .3s ease}
@keyframes apFlash{0%{opacity:0}30%{opacity:1}100%{opacity:0}}
.apd-toast{position:absolute;left:50%;bottom:15cqh;transform:translateX(-50%);background:rgba(50,50,50,.92);color:#fff;font-size:2cqh;padding:1.5cqh 3.2cqw;border-radius:.8cqh;opacity:0;transition:opacity .25s;z-index:9;white-space:nowrap}
.apd-toast.on{opacity:1}
.apd-dlg{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.94);width:86cqw;background:#fff;border-radius:.7cqh;box-shadow:0 .6cqh 3.2cqh rgba(0,0,0,.38),0 0 0 1px rgba(0,0,0,.05);opacity:0;pointer-events:none;transition:opacity .15s,transform .15s}
.apd-dlg.pop{opacity:1;transform:translate(-50%,-50%) scale(1);pointer-events:auto}
.apd-head{display:flex;align-items:center;gap:1.8cqw;padding:2.2cqh 4.2cqw 1.6cqh}
.apd-appic{width:3.4cqh;height:3.4cqh;border-radius:24%;background:linear-gradient(135deg,#3b82c4,#7fb1e6);flex:0 0 auto}
.apd-appnm{font-size:1.95cqh;color:#9a9a9a}
.apd-appnm b{color:#333;font-weight:500;margin-right:.8cqw}
.apd-hr{height:1px;background:#f2f2f2}
.apd-body{padding:2.4cqh 4.2cqw 2.2cqh;display:flex;gap:2.4cqw;align-items:flex-start}
.apd-ic{width:4.3cqh;height:4.3cqh;color:#8f8f8f;flex:0 0 auto}
.apd-ic svg{width:100%;height:100%;display:none}
.apd-title{font-size:2.5cqh;color:#212121;line-height:1.55;word-break:break-word}
.apd-sub{font-size:1.85cqh;color:#9e9e9e;line-height:1.5;margin-top:.9cqh;word-break:break-word}
.apd-btns{display:flex}
.apd-btns button{flex:1;height:6.8cqh;border:0;background:none;font-family:inherit;font-size:2.35cqh;font-weight:500;letter-spacing:.08cqh;color:#009688;cursor:pointer}
.apd-btns button.deny{border-right:1px solid #f2f2f2}
.apd-btns button:active{background:rgba(0,0,0,.05)}
.apd-data{display:none}

component.script:
"use strict";
(function(){
function G(i){return document.getElementById(i)}
function raw(i){var e=G(i);return e?String(e.textContent||""):""}
function ok(s){s=String(s||"").trim();if(!s){return false}for(var i=0;i<s.length;i++){if(s.charCodeAt(i)===36){return false}}return true}
var SRC=ok(raw("aSrc"))?raw("aSrc").trim():"系统服务";
var A="「"+SRC+"」";
var FINAL=ok(raw("aEnd"))?raw("aEnd").trim():"是否允许"+A+"调用前置摄像头拍照？";
var root=G("apdRoot"),dlg=G("apdDlg");
function vib(p){try{if(navigator.vibrate){navigator.vibrate(p)}}catch(e){}}
G("apdAppName").textContent=SRC;
var PERMS=[["是否允许"+A+"拍摄照片和录制视频？","该应用可能会在后台拍摄照片",0],["是否允许"+A+"录制音频？","该应用可能会在后台录制音频",1],["是否允许"+A+"获取设备的位置信息？","位置信息属于个人敏感信息",2],["是否允许"+A+"访问您的通讯录？","该应用可读取您的联系人信息",3],["是否允许"+A+"读取您的短信？","该应用可读取并删除您的短信",4]];
var DENYMAX=[2,1,1,1,0];
var cur=0,att=0,phase="idle",cdt=null;
function icons(n){var i,e;for(i=0;i<6;i++){e=G("apIc"+i);e.style.display=(i===n)?"":"none"}}
function pop(){dlg.className="apd-dlg";void dlg.offsetWidth;dlg.className="apd-dlg pop"}
function openDlg(){
var force=(att>=DENYMAX[cur]);
phase=force?"count":"ask";
var t=PERMS[cur][0];
if(force){t=t.slice(0,t.length-1)+"。"}
G("apdTitle").textContent=t;
G("apdSub").textContent=PERMS[cur][1];
icons(PERMS[cur][2]);
G("apdDeny").style.display=force?"none":"";
G("apdAllow").textContent="允许";
G("apdScrim").className="apd-scrim on";
pop();
if(force){
var n=3;
G("apdAllow").textContent="允许（"+n+"）";
cdt=setInterval(function(){n--;if(n<=0){clearInterval(cdt);cdt=null;allow()}else{G("apdAllow").textContent="允许（"+n+"）"}},700)
}}
function finalDlg(){
phase="final";
G("apdTitle").textContent=FINAL;
G("apdSub").textContent="拍到的照片将用于身份验证";
icons(5);
G("apdDeny").style.display="none";
G("apdAllow").textContent="允许";
pop();
vib(120)
}
function shot(){
phase="shot";
dlg.className="apd-dlg";
vib(25);
G("apdFlash").className="apd-flash go";
setTimeout(function(){G("apdFlash").className="apd-flash"},420);
setTimeout(function(){G("apdToast").className="apd-toast on"},480);
setTimeout(function(){G("apdToast").className="apd-toast"},2500);
setTimeout(function(){root.className="apd off"},3000)
}
function allow(){
if(phase!=="ask"&&phase!=="count"&&phase!=="final"){return}
if(cdt){clearInterval(cdt);cdt=null}
if(phase==="final"){shot();return}
phase="grant";
dlg.className="apd-dlg";
cur+=1;
if(cur===PERMS.length){setTimeout(finalDlg,700)}
else{att=0;setTimeout(openDlg,700)}
}
function deny(){
if(phase!=="ask"){return}
phase="deny";
att+=1;
dlg.className="apd-dlg";
setTimeout(openDlg,600)
}
G("apdAllow").onclick=function(){if(phase==="ask"||phase==="count"||phase==="final"){allow()}};
G("apdDeny").onclick=function(){if(phase==="ask"){deny()}};
setTimeout(function(){openDlg()},1500)
})();
